#!/usr/bin/env python3
import json
import sqlite3
from pathlib import Path

db = Path.home() / ".config/Cursor/User/globalStorage/state.vscdb"
conn = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
conn.row_factory = sqlite3.Row
cur = conn.cursor()

# composerHeaders table
if "composerHeaders" in [r[0] for r in cur.execute("SELECT name FROM sqlite_master WHERE type='table'")]:
    rows = cur.execute("SELECT * FROM composerHeaders LIMIT 5").fetchall()
    print("composerHeaders cols:", rows[0].keys() if rows else "empty")
    print("composerHeaders count:", cur.execute("SELECT COUNT(*) FROM composerHeaders").fetchone()[0])
    for r in cur.execute("SELECT * FROM composerHeaders LIMIT 3"):
        print(dict(r))

# sample composerData keys
for (key,) in cur.execute("SELECT key FROM cursorDiskKV WHERE key LIKE 'composerData:%' LIMIT 3"):
    val = cur.execute("SELECT value FROM cursorDiskKV WHERE key=?", (key,)).fetchone()[0]
    try:
        data = json.loads(val)
        print("composerData key:", key[:40])
        print("  keys:", list(data.keys())[:15] if isinstance(data, dict) else type(data))
        if isinstance(data, dict):
            for k in ("workspaceUri", "workspaceFolder", "context", "fullConversationHeadersOnly"):
                if k in data:
                    print(f"  {k}:", str(data[k])[:120])
    except Exception as e:
        print("  parse err", e)

# workspace storage folders
ws_root = Path.home() / ".config/Cursor/User/workspaceStorage"
for ws in sorted(ws_root.iterdir())[:8]:
    wj = ws / "workspace.json"
    if wj.exists():
        print("workspace.json", ws.name, wj.read_text()[:200])

conn.close()

